/**
 * An application's command menus in one row (`design/components/menubar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/menubar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input } from '@angular/core'

import * as zag from '@zag-js/menu'

import {
  Icon,
  MEMBER_PROVIDERS,
  Portal,
  Ref,
  Spread,
  agentMember,
  cell,
  chooseMenubarEntry,
  classes,
  derived,
  elementRef,
  followHighlight,
  getters,
  menubarChoices,
  menubarEdge,
  menubarEntries,
  menubarNeighbour,
  menubarStop,
  mergeParts,
  mountEffect,
  normalizeProps,
  provideOwner,
  roveMenubar,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMediaQuery,
  useMember,
  watchEffect,
  type Each,
  type IconProps,
} from '@polymorph/angular'
import { usePresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/overlays/menubar.module.css'
import { Button, type ButtonProps } from '../controls/Button'
import { Kbd } from '../structure/Kbd'
import { Menu, type MenuProps, type MenuEntry } from './Menu'
import { MenubarSubmenu, type MenubarSubmenuProps } from './MenubarSubmenu'

export interface MenubarMenu {
  label: string
  entries: MenuEntry[]
  disabled?: boolean
}

/** An application's command menus in one row: the inputs it takes, by the React member's prop names. */
export interface MenubarProps {
  /**
   * The title whose menu is open on mount, for galleries and tests; screens let the user open
   * it.
   */
  defaultOpen?: string
  /**
   * Names the bar, and the one Button the bar becomes at a phone's width.
   */
  label: string
  menus: MenubarMenu[]
}

/** What Menubar hands its compound parts. */
export interface MenubarOwner {
  readonly api: zag.Api
  readonly service: zag.Service
  readonly handOff: unknown
}

/** An application's command menus in one row. */
@Component({
  selector: 'pm-menubar',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS, provideOwner('Menubar')],
  imports: [Portal, Ref, Spread, Button, Icon, Kbd, Menu, MenubarSubmenu],
  // prettier-ignore
  template: `@if (e1()) {<div
[attr.class]="e2()"
data-member="menubar"
><pm-menu
[items]="e3()"
><ng-container ngProjectAs="[slot=trigger]"><pm-button
variant="ghost"
tone="neutral"
[iconOnly]="e4()"
icon="overflow"
[label]="e5()"
></pm-button></ng-container></pm-menu></div>} @else {<!-- bar -->
<div
[attr.class]="e6()"
role="menubar"
[attr.aria-label]="e7()"
data-member="menubar"
[pmRef]="bar"
>@for (menu of e8(); track e9(menu)) {<!-- title -->
<button
[pmSpread]="e10(menu)"
>{{ e11(menu) }}</button>}</div>
<ng-template pmPortal>@if (e12()) {<div
[pmSpread]="e13()"
><!-- panel -->
<div
[pmSpread]="e14()"
[pmRef]="panel"
>@for (entry of e15(); track e16($index); let index = $index) {@if (e17(entry)) {<div
[pmSpread]="e18(entry)"
></div>} @else if (e19(entry)) {<div
[attr.class]="e20(entry)"
>{{ e21(entry) }}</div>} @else if (e22(entry)) {<div
[pmSpread]="e23(entry)"
><span
[attr.class]="e24(entry)"
>@if (e25(entry)) {<pm-icon
name="confirm"
size="sm"
></pm-icon>}</span>
<span
[attr.class]="e26(entry)"
>{{ e27(entry) }}</span></div>} @else if (e28(entry)) {<pm-menubar-submenu
[entry]="e29(entry)"
></pm-menubar-submenu>} @else {<div
[pmSpread]="e30(entry)"
>@if (e31(entry)) {<span
[attr.class]="e32(entry)"
><pm-icon
[name]="e33(entry)"
size="sm"
></pm-icon></span>}
<span
[attr.class]="e34(entry)"
>{{ e35(entry) }}</span>
@if (e36(entry)) {<span
[attr.class]="e37(entry)"
><pm-kbd>{{ e38(entry) }}</pm-kbd></span>}</div>}}</div></div>}</ng-template>}`,
})
export class Menubar {
  /**
   * The title whose menu is open on mount, for galleries and tests; screens let the user open
   * it.
   */
  readonly defaultOpen = input<MenubarProps['defaultOpen']>(undefined)
  /**
   * Names the bar, and the one Button the bar becomes at a phone's width.
   */
  readonly label = input.required<MenubarProps['label']>()
  readonly menus = input.required<MenubarProps['menus']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      defaultOpen: () => this.defaultOpen(),
      label: () => this.label(),
      menus: () => this.menus(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly last = cell(() => (this.$p.defaultOpen ?? null) as string | null)
  protected readonly bar = elementRef<HTMLElement>()
  protected readonly panel = elementRef<HTMLElement>()
  protected readonly phone = useMediaQuery('phone')
  protected readonly stop = derived(() => menubarStop(this.$p.menus, this.last.value))
  protected readonly collapsed = derived(() => menubarEntries(this.$p.menus))
  protected readonly documentDirection = useDirection(() => this.bar.value)
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          defaultOpen: this.$p.defaultOpen !== undefined,
          defaultTriggerValue: this.$p.defaultOpen,
          positioning: { placement: 'bottom-start', gutter: 2 },
          onSelect: (details) => {
            this.entries.value.forEach(
              (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
            )
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly entries = derived(
    () => this.$p.menus.find((menu) => menu.label === this.api.value.triggerValue)?.entries ?? [],
  )
  protected readonly handOff = derived(
    () =>
      (event: KeyboardEvent, child?: { setOpen(open: boolean): void }): void => {
        const to = menubarNeighbour(event, this.bar.value, this.panel.value)
        const next = to === undefined ? undefined : this.$p.menus[to]
        if (next === undefined) return
        event.preventDefault()
        event.stopPropagation()
        child?.setOpen(false)
        this.api.value.setTriggerValue(next.label)
        this.$.afterRender(() => {
          const first = menubarEdge(this.panel.value, 'first')?.getAttribute('data-value')
          if (first) this.api.value.setHighlightedValue(first)
        })
      },
  )
  protected readonly hover = derived(() => (event: Event, menu: MenubarMenu): void => {
    if (!(event instanceof PointerEvent) || event.pointerType !== 'mouse') return
    if (menu.disabled === true) return
    if (!this.api.value.open || this.api.value.triggerValue === menu.label) return
    this.api.value.setTriggerValue(menu.label)
    // The machine reads an empty value as no row, so the last menu's row is not carried over.
    this.api.value.setHighlightedValue('')
  })
  protected readonly present = setup(() =>
    usePresence(
      () => this.api.value.open && !this.phone(),
      () => this.panel.value,
    ),
  )
  private release3: (() => void) | undefined

  constructor() {
    this.$.owner = getters<MenubarOwner>({
      api: () => this.api.value,
      service: () => this.service.value,
      handOff: () => this.handOff.value,
    })
    watchEffect(
      () => this.api.value.highlightedValue,
      () => this.effect1(),
      true,
    )
    watchEffect(
      () => this.api.value.triggerValue,
      () => this.effect2(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    mountEffect(() => this.effect3())
  }

  protected e1() {
    return this.phone()
  }

  protected e2() {
    if (!this.phone()) return undefined as never
    return styles.collapsed
  }

  protected e3(): MenuProps['items'] {
    if (!this.phone()) return undefined as never
    return this.collapsed.value
  }

  protected e4(): ButtonProps['iconOnly'] {
    if (!this.phone()) return undefined as never
    return true
  }

  protected e5(): ButtonProps['label'] {
    if (!this.phone()) return undefined as never
    return this.$p.label
  }

  protected e6() {
    if (this.phone()) return undefined as never
    return styles.bar
  }

  protected e7() {
    if (this.phone()) return undefined as never
    return this.$p.label
  }

  e8() {
    if (this.phone()) return undefined as never
    return this.$p.menus
  }

  protected e9(menu: Each<ReturnType<Menubar['e8']>>) {
    return menu.label
  }

  protected h1($event: KeyboardEvent): void {
    if (this.phone()) return
    roveMenubar($event)
  }

  protected h2($event: PointerEvent, menu: Each<ReturnType<Menubar['e8']>>): void {
    if (this.phone()) return
    this.hover.value($event, menu)
  }

  protected h3(menu: Each<ReturnType<Menubar['e8']>>): void {
    if (this.phone()) return
    this.last.value = menu.label
  }

  protected e10(menu: Each<ReturnType<Menubar['e8']>>) {
    if (this.phone()) return undefined as never
    return mergeParts(this.api.value.getTriggerProps({ value: menu.label }), {
      class: styles.title,
      role: 'menuitem',
      'data-menubar-part': 'title',
      'data-state':
        this.api.value.open && this.api.value.triggerValue === menu.label ? 'open' : 'closed',
      'aria-expanded': this.api.value.open && this.api.value.triggerValue === menu.label,
      'aria-controls':
        this.api.value.open && this.api.value.triggerValue === menu.label
          ? this.api.value.getContentProps().id
          : undefined,
      disabled: menu.disabled === true,
      'data-disabled': menu.disabled === true ? '' : undefined,
      tabindex: menu.label === this.stop.value ? 0 : -1,
      onKeydown: ($event: KeyboardEvent) => this.h1($event),
      onPointerenter: ($event: PointerEvent) => this.h2($event, menu),
      onFocus: () => this.h3(menu),
    })
  }

  protected e11(menu: Each<ReturnType<Menubar['e8']>>) {
    if (this.phone()) return undefined as never
    return menu.label
  }

  protected e12() {
    if (this.phone()) return undefined as never
    return this.present.value()
  }

  protected e13() {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    return mergeParts(this.api.value.getPositionerProps())
  }

  protected h4(): void {
    if (this.phone()) return
    if (!this.present.value()) return
    followHighlight(this.panel.value, this.api.value.highlightedValue)
  }

  protected h5($event: KeyboardEvent): void {
    if (this.phone()) return
    if (!this.present.value()) return
    this.handOff.value($event)
  }

  protected e14() {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    return mergeParts(this.api.value.getContentProps(), {
      class: styles.content,
      style: {
        '--radix-dropdown-menu-content-available-height': 'var(--available-height)',
        '--radix-dropdown-menu-content-transform-origin': 'var(--transform-origin)',
      },
      hidden: undefined,
      'data-menubar-part': 'panel',
      'data-member': 'menubar',
      onFocus: () => this.h4(),
      onKeydownCapture: ($event: KeyboardEvent) => this.h5($event),
    })
  }

  e15() {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    return this.entries.value
  }

  protected e16(index: number) {
    return index
  }

  protected e17(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    return entry.kind === 'separator'
  }

  protected e18(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (!(entry.kind === 'separator')) return undefined as never
    return mergeParts(this.api.value.getSeparatorProps(), { class: styles.separator })
  }

  protected e19(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    return entry.kind === 'label'
  }

  protected e20(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (!(entry.kind === 'label')) return undefined as never
    return styles.groupLabel
  }

  protected e21(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (!(entry.kind === 'label')) return undefined as never
    return entry.label
  }

  protected e22(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    return entry.kind === 'checkbox'
  }

  protected h6(entry: Each<ReturnType<Menubar['e15']>>): void {
    if (this.phone()) return
    if (!this.present.value()) return
    if (entry.kind === 'separator') return
    if (entry.kind === 'label') return
    if (!(entry.kind === 'checkbox')) return
    this.api.value.setHighlightedValue(entry.label)
  }

  protected e23(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (!(entry.kind === 'checkbox')) return undefined as never
    return mergeParts(
      this.api.value.getOptionItemProps({
        type: 'checkbox',
        value: entry.label,
        checked: entry.checked,
        disabled: entry.disabled,
        closeOnSelect: false,
        onCheckedChange: entry.onCheckedChange,
      }),
      {
        class: classes(styles.item, styles.checkbox),
        tabindex: '-1',
        onFocus: () => this.h6(entry),
      },
    )
  }

  protected e24(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (!(entry.kind === 'checkbox')) return undefined as never
    return styles.check
  }

  protected e25(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (!(entry.kind === 'checkbox')) return undefined as never
    return entry.checked
  }

  protected e26(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (!(entry.kind === 'checkbox')) return undefined as never
    return styles.label
  }

  protected e27(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (!(entry.kind === 'checkbox')) return undefined as never
    return entry.label
  }

  protected e28(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (entry.kind === 'checkbox') return undefined as never
    return entry.kind === 'submenu'
  }

  protected e29(entry: Each<ReturnType<Menubar['e15']>>): MenubarSubmenuProps['entry'] {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (entry.kind === 'checkbox') return undefined as never
    if (!(entry.kind === 'submenu')) return undefined as never
    return entry
  }

  protected h7(entry: Each<ReturnType<Menubar['e15']>>): void {
    if (this.phone()) return
    if (!this.present.value()) return
    if (entry.kind === 'separator') return
    if (entry.kind === 'label') return
    if (entry.kind === 'checkbox') return
    if (entry.kind === 'submenu') return
    this.api.value.setHighlightedValue(entry.label)
  }

  protected e30(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (entry.kind === 'checkbox') return undefined as never
    if (entry.kind === 'submenu') return undefined as never
    return mergeParts(
      this.api.value.getItemProps({ value: entry.label, disabled: entry.disabled }),
      {
        class: styles.item,
        'data-tone': entry.tone ?? 'neutral',
        tabindex: '-1',
        onFocus: () => this.h7(entry),
      },
    )
  }

  protected e31(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (entry.kind === 'checkbox') return undefined as never
    if (entry.kind === 'submenu') return undefined as never
    return entry.icon !== undefined
  }

  protected e32(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (entry.kind === 'checkbox') return undefined as never
    if (entry.kind === 'submenu') return undefined as never
    if (!(entry.icon !== undefined)) return undefined as never
    return styles.glyph
  }

  protected e33(entry: Each<ReturnType<Menubar['e15']>>): IconProps['name'] {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (entry.kind === 'checkbox') return undefined as never
    if (entry.kind === 'submenu') return undefined as never
    if (!(entry.icon !== undefined)) return undefined as never
    return entry.icon
  }

  protected e34(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (entry.kind === 'checkbox') return undefined as never
    if (entry.kind === 'submenu') return undefined as never
    return styles.label
  }

  protected e35(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (entry.kind === 'checkbox') return undefined as never
    if (entry.kind === 'submenu') return undefined as never
    return entry.label
  }

  protected e36(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (entry.kind === 'checkbox') return undefined as never
    if (entry.kind === 'submenu') return undefined as never
    return entry.kbd !== undefined
  }

  protected e37(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (entry.kind === 'checkbox') return undefined as never
    if (entry.kind === 'submenu') return undefined as never
    if (!(entry.kbd !== undefined)) return undefined as never
    return styles.hint
  }

  protected e38(entry: Each<ReturnType<Menubar['e15']>>) {
    if (this.phone()) return undefined as never
    if (!this.present.value()) return undefined as never
    if (entry.kind === 'separator') return undefined as never
    if (entry.kind === 'label') return undefined as never
    if (entry.kind === 'checkbox') return undefined as never
    if (entry.kind === 'submenu') return undefined as never
    if (!(entry.kbd !== undefined)) return undefined as never
    return entry.kbd
  }

  private effect1(): void {
    followHighlight(this.panel.value, this.api.value.highlightedValue)
  }

  private effect2(): void {
    void (this.api.value.triggerValue && (this.last.value = this.api.value.triggerValue))
  }

  private effect3(): void {
    this.release3?.()
    const ran = agentMember({
      member: 'Menubar',
      element: () => this.bar.value,
      state: () => ({ open: this.api.value.open, entries: menubarChoices(this.$p.menus) }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) =>
            chooseMenubarEntry(this.$p.menus, value) &&
            this.api.value.open &&
            this.api.value.setOpen(false),
        },
        close: () => this.api.value.open && this.api.value.setOpen(false),
      },
    })
    this.release3 = () => {
      ran()
    }
  }
}
